        if attacked(b2, move[2:4], not wtm):
            s -= 3
        # promotion bonus
        if len(move) == 5:
            s += VALUE[move[4]] * 5
        return s

    best = None
    bs = -99999
    for m in legal:
        s = score(m)
        if s > bs:
            bs = s
            best = m
    return best


